<script setup lang="ts">import { CircleAlert, CircleCheck, CircleDashed, CircleOff } from 'lucide-vue-next'; import { computed } from 'vue'; import { statusLabel } from '../utils/format'; const props=defineProps<{status:string}>(); const icon=computed(()=>['active','approved'].includes(props.status)?CircleCheck:['rejected','revoked','inactive'].includes(props.status)?CircleOff:['pending_mentor','pending_teacher','pending','pending_configuration'].includes(props.status)?CircleDashed:CircleAlert);</script>
<template><span class="status-badge" :class="status"><component :is="icon" :size="13"/>{{statusLabel(status)}}</span></template>
